class Solution {
public:
    bool carPooling(vector<vector<int>>& trips, int capacity) {
        map<int, int> change;
        for (auto& t : trips) {
            change[t[1]] += t[0];
            change[t[2]] -= t[0];
        }
        int onboard = 0;
        for (auto& [stop, d] : change) {
            onboard += d;
            if (onboard > capacity) return false;
        }
        return true;
    }
};
